  var data = [
    {d:"Feb28",v:74.66},{d:"Mar4",v:90.90},{d:"Mar9",v:85.27},{d:"Mar16",v:88.40},
    {d:"Mar23",v:91.20},{d:"Mar30",v:93.50},{d:"Apr6",v:96.80},{d:"Apr8",v:93.80},
    {d:"Apr14",v:98.40},{d:"Apr21",v:103.60},{d:"Apr28",v:107.20},{d:"May5",v:109.47},
