  ];
  var n = data.length;
  var margin = {left:62,right:24,top:18,bottom:46};
  var W = 680, H = 300;
  var PW = W - margin.left - margin.right;
  var PH = H - margin.top - margin.bottom;

  var vals = data.map(function(d){return d.v;});
  var minV = 70, maxV = 115;
  var xS = function(i){ return margin.left + (i/(n-1))*PW; };
  var yS = function(v){ return margin.top + PH - ((v - minV)/(maxV - minV))*PH; };

  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("xmlns","http://www.w3.org/2000/svg");
  svg.setAttribute("width","100%");

  function el(tag,attrs){
    var e = document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(var k in attrs) e.setAttribute(k,attrs[k]);
    return e;
  }
  function txt(s,attrs){
    var e = document.createElementNS("http://www.w3.org/2000/svg","text");
    for(var k in attrs) e.setAttribute(k,attrs[k]);
    e.textContent = s;
    return e;
  }

  // Gridlines
  var yTicks = [75,80,85,90,95,100,105,110];
  yTicks.forEach(function(v){
    var y = yS(v);
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:y,y2:y,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(txt("$"+v,{x:margin.left-6,y:y+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });

  // X axis
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  var xLabelIdx = [0,3,6,9,12,15,17];
  xLabelIdx.forEach(function(i){
    svg.appendChild(txt(data[i].d,{x:xS(i),y:margin.top+PH+12,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });

  // Ceasefire event band (Apr 8 = index 7)
  var cBandX = xS(7);
  var cBandW = xS(10) - xS(7);
  svg.appendChild(el("rect",{x:cBandX,y:margin.top,width:cBandW,height:PH,fill:"#2e7d32","fill-opacity":"0.07"}));
  svg.appendChild(txt("CEASEFIRE",{x:cBandX+cBandW/2,y:margin.top+10,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#2e7d32","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Peak zone band (Apr 28 - May 5 = index 11-11)
  var pBandX = xS(10);
  var pBandW = xS(12) - xS(10);
  svg.appendChild(el("rect",{x:pBandX,y:margin.top,width:pBandW,height:PH,fill:"#c0392b","fill-opacity":"0.05"}));
  svg.appendChild(txt("PEAK ZONE",{x:pBandX+pBandW/2,y:margin.top+10,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#8a3030","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Area fill under line
  var areaPath = "M"+xS(0)+","+yS(data[0].v);
  for(var i=1;i<n;i++) areaPath += " L"+xS(i)+","+yS(data[i].v);
  areaPath += " L"+xS(n-1)+","+(margin.top+PH)+" L"+xS(0)+","+(margin.top+PH)+" Z";
  svg.appendChild(el("path",{d:areaPath,fill:"#4a5568","fill-opacity":"0.08"}));

  // Line
  var linePath = "M"+xS(0)+","+yS(data[0].v);
  for(var i=1;i<n;i++) linePath += " L"+xS(i)+","+yS(data[i].v);
  svg.appendChild(el("path",{d:linePath,fill:"none",stroke:"#4a5568","stroke-width":"2"}));

  // $100 reference line
  var ref100Y = yS(100);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:ref100Y,y2:ref100Y,stroke:"#7a3030","stroke-dasharray":"3,3","stroke-width":"1"}));
  svg.appendChild(txt("$100",{x:650,y:ref100Y-3,"text-anchor":"end","font-size":"7.5","fill":"#7a3030","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Moving average (5-period simple)
  var maPath = "";
  for(var i=4;i<n;i++){
    var ma = (data[i].v+data[i-1].v+data[i-2].v+data[i-3].v+data[i-4].v)/5;
    if(i===4) maPath = "M"+xS(i)+","+yS(ma);
    else maPath += " L"+xS(i)+","+yS(ma);
  }
  svg.appendChild(el("path",{d:maPath,fill:"none",stroke:"#888888","stroke-width":"1","stroke-dasharray":"4,2"}));
  svg.appendChild(txt("5-day MA",{x:xS(n-1)-4,y:yS((data[17].v+data[16].v+data[15].v+data[14].v+data[13].v)/5)-5,"text-anchor":"end","font-size":"7.5","fill":"#888","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Event markers: June 9-10 re-escalation
  var evX = xS(16);
  svg.appendChild(el("line",{x1:evX,x2:evX,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":"0.5","stroke-dasharray":"2,3","stroke-width":"1"}));
  svg.appendChild(txt("US STRIKES",{x:evX-4,y:margin.top+22,"text-anchor":"end","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  svg.appendChild(txt("JUN 9-10",{x:evX-4,y:margin.top+31,"text-anchor":"end","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Gold pill at endpoint
  var lastX = xS(n-1), lastY = yS(data[n-1].v);
  var pillW = 58, pillH = 16;
  var pillX = lastX - pillW - 6;
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:lastY-pillH/2,width:pillW,height:pillH,fill:"#e8a825",rx:"3"}));
  svg.appendChild(txt("$88.72",{x:pillX+pillW/2,y:lastY+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Peak annotation
  var peakX = xS(11), peakY = yS(109.47);
  svg.appendChild(el("circle",{cx:peakX,cy:peakY,r:3,fill:"#8a3030"}));
  svg.appendChild(txt("$109.47 PEAK",{x:peakX-5,y:peakY-6,"text-anchor":"end","font-size":"8","fill":"#444","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  var container = document.currentScript ? document.currentScript.parentNode : null;
  if(container) container.appendChild(svg);
})();
</script>
