<script>
(function(){
  var data = [
    {d:"Jan24",v:5.00},{d:"Mar24",v:5.00},{d:"Apr24",v:5.00},{d:"Jun24",v:4.75},
    {d:"Jul24",v:4.50},{d:"Sep24",v:4.25},{d:"Oct24",v:3.75},{d:"Dec24",v:3.25},
    {d:"Jan25",v:3.00},{d:"Mar25",v:2.75},{d:"Apr25",v:2.50},{d:"Jun25",v:2.25},
    {d:"Jul25",v:2.25},{d:"Sep25",v:2.25},{d:"Oct25",v:2.25},{d:"Dec25",v:2.25},
    {d:"Jan26",v:2.25},{d:"Mar26",v:2.25},{d:"Apr26",v:2.25},{d:"Jun26",v:2.25}
  ];
  var n = data.length;
  var margin = {left:62,right:24,top:18,bottom:46};
  var W = 680, H = 300;
  var PW = W - margin.left - margin.right;
  var PH = H - margin.top - margin.bottom;
  var minV = 1.5, maxV = 5.5;

  var xS = function(i){ return margin.left + (i/(n-1))*PW; };
  var yS = function(v){ return margin.top + PH - ((v - minV)/(maxV - minV))*PH; };

  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("xmlns","http://www.w3.org/2000/svg");
  svg.setAttribute("width","100%");

  function el(tag,attrs){
    var e = document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(var k in attrs) e.setAttribute(k,attrs[k]);
    return e;
  }
  function txt(s,attrs){
    var e = document.createElementNS("http://www.w3.org/2000/svg","text");
    for(var k in attrs) e.setAttribute(k,attrs[k]);
    e.textContent = s;
    return e;
  }

  // Gridlines and Y labels
  var yTicks = [2.0,2.5,3.0,3.5,4.0,4.5,5.0];
  yTicks.forEach(function(v){
    var y = yS(v);
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:y,y2:y,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(txt(v.toFixed(2)+"%",{x:margin.left-6,y:y+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });

  // X axis
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  var xLabelIdx = [0,3,6,9,12,15,19];
  xLabelIdx.forEach(function(i){
    svg.appendChild(txt(data[i].d,{x:xS(i),y:margin.top+PH+12,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });

  // Cutting cycle band (Jun 24 to Jun 25, index 3 to 11)
  var cutX = xS(3), cutW = xS(11) - xS(3);
  svg.appendChild(el("rect",{x:cutX,y:margin.top,width:cutW,height:PH,fill:"#2e7d32","fill-opacity":"0.07"}));
  svg.appendChild(txt("CUTTING CYCLE",{x:cutX+cutW/2,y:margin.top+10,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#2e7d32","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Hold period band (Jun 25 onwards, index 11 to 19)
  var holdX = xS(11), holdW = xS(19) - xS(11);
  svg.appendChild(el("rect",{x:holdX,y:margin.top,width:holdW,height:PH,fill:"#4a5568","fill-opacity":"0.06"}));
  svg.appendChild(txt("5 CONSECUTIVE HOLDS",{x:holdX+holdW/2,y:margin.top+10,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#4a5568","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Step line
  var stepPath = "M"+xS(0)+","+yS(data[0].v);
  for(var i=1;i<n;i++){
    stepPath += " L"+xS(i)+","+yS(data[i-1].v);
    stepPath += " L"+xS(i)+","+yS(data[i].v);
  }
  svg.appendChild(el("path",{d:stepPath,fill:"none",stroke:"#4a5568","stroke-width":"2.5"}));

  // 2% target reference line
  var ref2Y = yS(2.0);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:ref2Y,y2:ref2Y,stroke:"#2e7d32","stroke-dasharray":"3,3","stroke-width":"1"}));
  svg.appendChild(txt("2% TARGET",{x:650,y:ref2Y-3,"text-anchor":"end","font-size":"7.5","fill":"#2e7d32","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Gold pill at current rate
  var lastX = xS(n-1), lastY = yS(data[n-1].v);
  var pillW = 54, pillH = 16;
  var pillX = lastX - pillW - 6;
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:lastY-pillH/2,width:pillW,height:pillH,fill:"#e8a825",rx:"3"}));
  svg.appendChild(txt("2.25%",{x:pillX+pillW/2,y:lastY+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Jun 10 event marker
  var evX = xS(19);
  svg.appendChild(el("line",{x1:evX,x2:evX,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":"0.5","stroke-dasharray":"2,3","stroke-width":"1"}));
  svg.appendChild(txt("JUN 10",{x:evX-5,y:margin.top+22,"text-anchor":"end","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  svg.appendChild(txt("HOLD",{x:evX-5,y:margin.top+31,"text-anchor":"end","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  var container = document.currentScript ? document.currentScript.parentNode : null;
  if(container) container.appendChild(svg);
})();
</script>
