    {d:"May25",v:1.8},{d:"Jun25",v:1.9},{d:"Jul25",v:2.0},{d:"Aug25",v:2.0},
    {d:"Sep25",v:1.9},{d:"Oct25",v:2.2},{d:"Nov25",v:2.0},{d:"Dec25",v:1.8},
    {d:"Jan26",v:1.9},{d:"Feb26",v:2.1},{d:"Mar26",v:2.4},{d:"Apr26",v:2.8}
  ];
  var core = [
    {d:"Jan25",v:2.7},{d:"Feb25",v:2.9},{d:"Mar25",v:2.8},{d:"Apr25",v:2.6},
    {d:"May25",v:2.5},{d:"Jun25",v:2.5},{d:"Jul25",v:2.6},{d:"Aug25",v:2.5},
    {d:"Sep25",v:2.4},{d:"Oct25",v:2.5},{d:"Nov25",v:2.4},{d:"Dec25",v:2.4},
    {d:"Jan26",v:2.5},{d:"Feb26",v:2.4},{d:"Mar26",v:2.4},{d:"Apr26",v:2.3}
  ];
  var n = headline.length;
  var margin = {left:62,right:24,top:18,bottom:46};
  var W = 680, H = 300;
  var PW = W - margin.left - margin.right;
  var PH = H - margin.top - margin.bottom;
  var minV = 0.5, maxV = 3.5;

  var xS = function(i){ return margin.left + (i/(n-1))*PW; };
  var yS = function(v){ return margin.top + PH - ((v - minV)/(maxV - minV))*PH; };

  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");

  function el(tag,attrs){
    var e = document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(var k in attrs) e.setAttribute(k,attrs[k]);
    return e;
  }
  function txt(s,attrs){
    var e = document.createElementNS("http://www.w3.org/2000/svg","text");
    for(var k in attrs) e.setAttribute(k,attrs[k]);
    e.textContent = s;
    return e;
  }

  // Gridlines
  [1.0,1.5,2.0,2.5,3.0].forEach(function(v){
    var y = yS(v);
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:y,y2:y,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(txt(v.toFixed(1)+"%",{x:margin.left-6,y:y+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });

  // X axis
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  var labelIdx = [0,3,6,9,12,15];
  labelIdx.forEach(function(i){
    svg.appendChild(txt(headline[i].d,{x:xS(i),y:margin.top+PH+12,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });

  // 2% target reference
  var ref2Y = yS(2.0);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:ref2Y,y2:ref2Y,stroke:"#2e7d32","stroke-dasharray":"3,3","stroke-width":"1"}));
  svg.appendChild(txt("2% TARGET",{x:650,y:ref2Y-3,"text-anchor":"end","font-size":"7.5","fill":"#2e7d32","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Conflict onset band (Mar 26 onward, index 14)
  var conflictX = xS(14);
  var conflictW = xS(n-1) - xS(14);
  svg.appendChild(el("rect",{x:conflictX,y:margin.top,width:conflictW,height:PH,fill:"#c0392b","fill-opacity":"0.05"}));
  svg.appendChild(txt("CONFLICT ONSET",{x:conflictX+conflictW/2,y:margin.top+10,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#8a3030","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Core line (grey dashed)
  var corePath = "M"+xS(0)+","+yS(core[0].v);
  for(var i=1;i<n;i++) corePath += " L"+xS(i)+","+yS(core[i].v);
  svg.appendChild(el("path",{d:corePath,fill:"none",stroke:"#6b7280","stroke-width":"1.8","stroke-dasharray":"5,3"}));

  // Headline line (solid)
  var hlPath = "M"+xS(0)+","+yS(headline[0].v);
  for(var i=1;i<n;i++) hlPath += " L"+xS(i)+","+yS(headline[i].v);
  svg.appendChild(el("path",{d:hlPath,fill:"none",stroke:"#4a5568","stroke-width":"2.5"}));

  // Series labels at end
  svg.appendChild(txt("Headline",{x:xS(n-1)-4,y:yS(headline[n-1].v)-6,"text-anchor":"end","font-size":"8","fill":"#4a5568","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  svg.appendChild(txt("Core trim",{x:xS(n-1)-4,y:yS(core[n-1].v)+12,"text-anchor":"end","font-size":"8","fill":"#6b7280","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Gold pill on headline endpoint
  var lastX = xS(n-1), lastY = yS(headline[n-1].v);
  var pillW = 46, pillH = 16;
  var pillX = lastX - pillW - 6;
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:lastY-pillH/2,width:pillW,height:pillH,fill:"#e8a825",rx:"3"}));
  svg.appendChild(txt("2.8%",{x:pillX+pillW/2,y:lastY+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Grey pill on core endpoint - right side offset
  var coreLastY = yS(core[n-1].v);
  var cpillW = 46, cpillH = 16;
  var cpillX = lastX + 6;
  if(cpillX + cpillW > 656) cpillX = lastX - cpillW - 6;
  svg.appendChild(el("circle",{cx:lastX,cy:coreLastY,r:3,fill:"#6b7280"}));
  svg.appendChild(el("rect",{x:cpillX,y:coreLastY-cpillH/2,width:cpillW,height:cpillH,fill:"#9ca3af",rx:"3"}));
  svg.appendChild(txt("2.3%",{x:cpillX+cpillW/2,y:coreLastY+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  var container = document.currentScript ? document.currentScript.parentNode : null;
  if(container) container.appendChild(svg);
})();
